mainPhaseFn:
async function mainPhase(args){
const base='docs/design/ui-refactor-2026-10-06/cloud';
const q=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const built=await tools.exec_command({cmd:'python3 '+base+'/build_cloud.py '+args,max_output_tokens:1500});
if(built.exit_code!==0)throw Error(built.output);
const mode=args.split(' ')[0];
const read=await tools.exec_command({cmd:'cat '+base+'/'+mode+'.js',max_output_tokens:24000});
if(read.exit_code!==0||read.output.length>50000)throw Error('Script oversized/read failed '+read.output.length+' '+built.output);
const result=await tools.mcp__codex_apps__figma_use_figma({fileKey:'OMLTC3yw3u2WDjOZhLnhaR',code:read.output,description:'Refine editable Gensen design '+args+' with reusable native components',skillNames:'figma-use,figma-generate-design,figma-generate-library'});
const receipt=base+'/batch-'+args.replace(/[^a-zA-Z0-9-]/g,'-')+'-'+Date.now()+'.json';
await tools.exec_command({cmd:'python3 -c '+q('from pathlib import Path; import sys; Path(sys.argv[1]).write_text(sys.argv[2])')+' '+q(receipt)+' '+q(JSON.stringify(result)),max_output_tokens:1000});
if(result.isError){text(result.content?.[0]);throw Error('Figma reported failure, inspect before retry');}
function unpack(r){if(typeof r==='string')return unpack(JSON.parse(r));if(r.screens||r.kit||r.flowRepairStates)return r;for(const k of ['structuredContent','result','data'])if(r[k])try{return unpack(r[k])}catch{};for(const c of r.content||[])if(c.type==='text')try{return unpack(c.text)}catch{};throw Error('No complete receipt');}
let data;try{data=unpack(result)}catch(e){text(result.content?.[0]);throw e;}
const parsed=receipt.replace('.json','-parsed.json');
const save=await tools.exec_command({cmd:'python3 -c '+q('import json,sys; from pathlib import Path; p=Path(sys.argv[1]); d=json.loads(sys.argv[2]); Path(sys.argv[3]).write_text(json.dumps(d,ensure_ascii=False,indent=2)); s=json.loads(p.read_text()); s.update({k:d[k] for k in ["overlayIndex","libraryHeight"] if k in d}); [s.setdefault(k,{}).update(d[k]) for k in ["kit","styles","components","componentSets","variables","icons"] if k in d]; s["completed"]=list(dict.fromkeys(s["completed"]+[x["id"] for x in d.get("screens",[])])); p.write_text(json.dumps(s,ensure_ascii=False,indent=2)); print(len(s["completed"]))')+' '+q(base+'/state.json')+' '+q(JSON.stringify(data))+' '+q(parsed),max_output_tokens:1200});
if(save.exit_code!==0)throw Error(save.output);
return {args,screens:data.screens,completed:Number(save.output.trim()),warnings:data.warnings?.length||0,newComponents:Object.keys(data.kit||{}).length};
}

avatarPhaseFn:
async function avatarPhase(args){
const base='docs/design/ui-refactor-2026-10-06/cloud/avatar';
const q=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const built=await tools.exec_command({cmd:'python3 '+base+'/build-avatar-phase.py '+args,max_output_tokens:1500});
if(built.exit_code!==0)throw Error(built.output);
const meta=JSON.parse(built.output.trim());
if(meta.phase==='wire'&&!meta.selected.length)return {done:true};
const read=await tools.exec_command({cmd:'cat '+q(base+'/'+meta.file),max_output_tokens:24000});
if(read.exit_code!==0||meta.characters!==read.output.length)throw Error('Script size/read mismatch '+meta.file+' '+read.output.length+'/'+meta.characters);
if(read.output.length>48000)throw Error('Oversize script');
const result=await tools.mcp__codex_apps__figma_use_figma({fileKey:'OMLTC3yw3u2WDjOZhLnhaR',code:read.output,description:'Complete editable Avatar '+args+' using existing shared components',skillNames:'figma-use,figma-generate-design,figma-generate-library'});
const receipt=base+'/result-'+meta.file.split('/').pop().replace('.js','-'+Date.now()+'.json');
await tools.exec_command({cmd:'python3 -c '+q('from pathlib import Path; import sys; Path(sys.argv[1]).write_text(sys.argv[2])')+' '+q(receipt)+' '+q(JSON.stringify(result)),max_output_tokens:1000});
if(result.isError){text(result.content?.[0]);throw Error('Figma error, inspect before retry');}
const merge=await tools.exec_command({cmd:'python3 '+base+'/merge_avatar_result.py '+q(receipt),max_output_tokens:2000});
if(merge.exit_code!==0){text(result.content?.[0]);throw Error(merge.output);}
return {phase:args,merged:merge.output.trim()};
}

preparedPhaseFn:
async function preparedPhase(path,kind,description){
const q=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const read=await tools.exec_command({cmd:'cat '+q(path),max_output_tokens:24500});if(read.exit_code!==0||read.output.length>50000)throw Error('Bad prepared script '+path);
const result=await tools.mcp__codex_apps__figma_use_figma({fileKey:'OMLTC3yw3u2WDjOZhLnhaR',code:read.output,description,skillNames:'figma-use,figma-generate-design,figma-generate-library'});
const receipt=path.replace('.js','-result-'+Date.now()+'.json');
const save=await tools.exec_command({cmd:'python3 -c '+q('from pathlib import Path;import sys;Path(sys.argv[1]).write_text(sys.argv[2])')+' '+q(receipt)+' '+q(JSON.stringify(result)),max_output_tokens:1000});if(save.exit_code!==0)throw Error(save.output);
if(result.isError){text(result.content?.[0]);throw Error('Figma failed, inspect before retry: '+receipt);}
if(kind==='avatar'){const merge=await tools.exec_command({cmd:'python3 docs/design/ui-refactor-2026-10-06/cloud/avatar/merge_avatar_result.py '+q(receipt),max_output_tokens:1500});if(merge.exit_code!==0)throw Error(merge.output);return {receipt,merged:merge.output.trim()};}
return {receipt,result};
}

customPhaseFn:
async function customPhase(cmd){
const build=await tools.exec_command({cmd,max_output_tokens:2500});if(build.exit_code!==0)throw Error(build.output);
let meta;for(const line of build.output.trim().split('\n'))try{const x=JSON.parse(line);if(x.file)meta=x;}catch{}
if(!meta)throw Error('No script path in builder output');
const r=await eval('('+load('preparedPhaseFn')+')')(meta.file,'raw','Complete reusable Gensen containers or an authored result state');
let d;try{d=JSON.parse(r.result.content.find(c=>c.type==='text').text);}catch(e){text({receipt:r.receipt});throw e;}
const q=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const merged=await tools.exec_command({cmd:'python3 -c '+q("import json,sys;from pathlib import Path;p=Path('docs/design/ui-refactor-2026-10-06/cloud/state.json');s=json.loads(p.read_text());d=json.loads(sys.argv[1]);[s.setdefault(k,{}).update(d[k]) for k in ['kit','styles','variables','components','componentSets','npcFlowScreens','flowScreens','flowSceneScreens'] if k in d];s.update({k:d[k]for k in ['overlayIndex','libraryHeight']if k in d});p.write_text(json.dumps(s,ensure_ascii=False,indent=2));q=p.parent/'final-rebuild-completed.json';old=json.loads(q.read_text())if q.exists()else[];q.write_text(json.dumps(list(dict.fromkeys(old+[x['id']for x in d.get('screens',[])])),indent=2))")+' '+q(JSON.stringify(d)),max_output_tokens:1000});if(merged.exit_code!==0)throw Error(merged.output);
return {receipt:r.receipt,screens:d.screens,npcFlowScreens:d.npcFlowScreens,newComponents:Object.keys(d.kit||{}).length,warnings:d.warnings};
}

repairPhaseFn:
async function repairPhase(indices){
const run=eval('('+load('mainPhaseFn')+')');let results=[];
try{results=[await run('screens '+indices.join(',')+' '+indices.length+' rebuild')];}
catch(e){if(indices.length>1&&/CalledProcessError|Script oversized/.test(String(e))){for(const i of indices)results.push(await run('screens '+i+' 1 rebuild'));}else throw e;}
const ids=results.flatMap(r=>r.screens.map(s=>s.id)),q=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const save=await tools.exec_command({cmd:'python3 -c '+q("import json,sys;from pathlib import Path;p=Path('docs/design/ui-refactor-2026-10-06/cloud/final-rebuild-completed.json');old=json.loads(p.read_text()) if p.exists() else [];p.write_text(json.dumps(list(dict.fromkeys(old+json.loads(sys.argv[1]))),indent=2))")+' '+q(JSON.stringify(ids)),max_output_tokens:500});
if(save.exit_code!==0)throw Error(save.output);return results;
}
